import journal from "./migrations/meta/_journal.json";

/** A migration generated by drizzle-kit, as bundled into the app. */
export interface Migration {
  /** File name without `.sql`, e.g. `0000_init`; identifies the migration. */
  tag: string;
  /** The SQL statements, split at drizzle-kit's `--> statement-breakpoint`. */
  statements: string[];
  /** SHA-256 (hex) of the SQL with LF line endings; detects edited migrations. */
  hash: string;
}

export interface Journal {
  entries: readonly { idx: number; tag: string }[];
}

const BREAKPOINT = "--> statement-breakpoint";

/**
 * The migrations in `./migrations`, bundled by Vite (the WebView cannot read
 * the file system). Order comes from drizzle-kit's journal; the snapshots are
 * not needed and not bundled.
 */
export function loadMigrations(): Promise<Migration[]> {
  const files = import.meta.glob<string>("./migrations/*.sql", {
    query: "?raw",
    import: "default",
    eager: true,
  });
  return parseMigrations(journal, (tag) => files[`./migrations/${tag}.sql`]);
}

/**
 * Builds the migrations in journal order; fails if a file is missing or the
 * journal is not numbered consecutively.
 */
export async function parseMigrations(
  { entries }: Journal,
  readSql: (tag: string) => string | undefined,
): Promise<Migration[]> {
  return Promise.all(
    entries.map(async ({ idx, tag }, position) => {
      if (idx !== position) {
        throw new Error(`Journal entry ${tag} has idx ${idx}, expected ${position}`);
      }
      const raw = readSql(tag);
      if (raw === undefined) {
        throw new Error(`Migration ${tag} is listed in the journal, but ${tag}.sql is missing`);
      }
      const sql = raw.replaceAll("\r\n", "\n");
      return {
        tag,
        statements: sql
          .split(BREAKPOINT)
          .map((statement) => statement.trim())
          .filter((statement) => statement.length > 0),
        hash: await sha256(sql),
      };
    }),
  );
}

async function sha256(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}
